        raise ProxiesUnavailableError("Proxy support missing but proxy use was requested!")
    if self.proxy_info and self.proxy_info.isgood():
        use_proxy = True
        (
            proxy_type,
            proxy_host,
            proxy_port,
            proxy_rdns,
            proxy_user,
            proxy_pass,
            proxy_headers,
        ) = self.proxy_info.astuple()

        host = proxy_host
        port = proxy_port
    else:
        use_proxy = False

        host = self.host
        port = self.port

    socket_err = None

    for res in socket.getaddrinfo(host, port, 0, socket.SOCK_STREAM):
        af, socktype, proto, canonname, sa = res
        try:
            if use_proxy:
                self.sock = socks.socksocket(af, socktype, proto)
                self.sock.setproxy(
                    proxy_type, proxy_host, proxy_port, proxy_rdns, proxy_user, proxy_pass, proxy_headers,
                )
            else:
                self.sock = socket.socket(af, socktype, proto)
                self.sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            # Different from httplib: support timeouts.
            if has_timeout(self.timeout):
                self.sock.settimeout(self.timeout)
                # End of difference from httplib.
            if self.debuglevel > 0:
                print("connect: (%s, %s) ************" % (self.host, self.port))
                if use_proxy:
                    print(
                        "proxy: %s ************"
                        % str((proxy_host, proxy_port, proxy_rdns, proxy_user, proxy_pass, proxy_headers,))
                    )
            if use_proxy:
                self.sock.connect((self.host, self.port) + sa[2:])
            else:
                self.sock.connect(sa)
